import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.name = 'filmstrip-carousel';

  // Design tokens
  const colors = {
    background: new THREE.Color('#0b0b10'),
    surface: new THREE.Color('#14141a'),
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38')
  };

  const cardCount = 5;
  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const cardPitch = 1.85;
  const bevelSize = 0.025;

  const cardNames = [
    'NA-01 MERIDIAN',
    'NA-02 NOCTURNE',
    'NA-03 SIGNAL',
    'NA-04 VANTAGE',
    'NA-05 ARCHIVE'
  ];

  // Load texture
  const texture = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  texture.colorSpace = THREE.SRGBColorSpace;

  // Animation state
  const state = {
    stripOffset: 0,
    focusIndex: Math.floor(cardCount / 2),
    isSnapping: false,
    snapTimeline: null,
    scrollTimer: null
  };

  // Create strip group rotated -18 degrees on y-axis
  const stripGroup = new THREE.Group();
  stripGroup.rotation.y = THREE.MathUtils.degToRad(-18);
  root.add(stripGroup);

  const cards = [];

  // Construct 5 cards
  for (let i = 0; i < cardCount; i++) {
    const cardContainer = new THREE.Group();
    const baseX = (i - Math.floor(cardCount / 2)) * cardPitch;
    cardContainer.position.x = baseX;

    cardContainer.userData = {
      index: i,
      baseX: baseX,
      opacity: 1.0
    };

    // Beveled frame (machined ink surface)
    const frameMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(cardWidth + bevelSize * 2, cardHeight + bevelSize * 2),
      new THREE.MeshStandardMaterial({
        color: colors.ink,
        roughness: 0.5,
        metalness: 0.55,
        clearcoat: 0.15
      })
    );
    frameMesh.position.z = -0.001;
    cardContainer.add(frameMesh);

    // Main card with texture
    const cardGeo = new THREE.PlaneGeometry(cardWidth, cardHeight);

    // Offset UVs per card for visual distinction
    const uvAttr = cardGeo.attributes.uv;
    const uvCol = i % 2;
    const uvRow = i > 2 ? 1 : 0;
    for (let j = 0; j < uvAttr.count; j++) {
      uvAttr.setXY(
        j,
        uvAttr.getX(j) * 0.5 + uvCol * 0.5,
        uvAttr.getY(j) * 0.5 + uvRow * 0.5
      );
    }
    uvAttr.needsUpdate = true;

    const cardMat = new THREE.MeshStandardMaterial({
      map: texture,
      color: colors.paper,
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15
    });

    const cardMesh = new THREE.Mesh(cardGeo, cardMat);
    cardContainer.add(cardMesh);

    // Accent underline (signal red, emissive)
    const underlineMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(cardWidth, 0.035),
      new THREE.MeshStandardMaterial({
        color: colors.accent,
        emissive: colors.accent,
        emissiveIntensity: 1.3,
        roughness: 0.5,
        metalness: 0.2
      })
    );
    underlineMesh.position.y = -(cardHeight / 2 + 0.1);
    underlineMesh.position.z = 0.002;
    underlineMesh.visible = false;
    cardContainer.add(underlineMesh);
    cardContainer.userData.underline = underlineMesh;

    stripGroup.add(cardContainer);
    cards.push(cardContainer);
  }

  // Render text via fontAtlas
  if (ctx.fontAtlas && ctx.fontAtlas.createTextGeometry) {
    // Headline: "The collection"
    const headlineGeo = ctx.fontAtlas.createTextGeometry('The collection', {
      fontSize: 0.68,
      fontFamily: 'Lora',
      fontWeight: 600,
      letterSpacing: -0.005,
      lineHeight: 1.1
    });
    if (headlineGeo) {
      const headlineMesh = new THREE.Mesh(
        headlineGeo,
        new THREE.MeshStandardMaterial({ color: colors.paper })
      );
      headlineMesh.position.set(-2.6, 1.5, 0);
      root.add(headlineMesh);
    }

    // Body: "Five calibres. One discipline."
    const bodyGeo = ctx.fontAtlas.createTextGeometry('Five calibres. One discipline.', {
      fontSize: 0.26,
      fontFamily: 'JetBrains Mono',
      fontWeight: 400,
      letterSpacing: 0,
      lineHeight: 1.5
    });
    if (bodyGeo) {
      const bodyMesh = new THREE.Mesh(
        bodyGeo,
        new THREE.MeshStandardMaterial({ color: colors.paper })
      );
      bodyMesh.position.set(-2.6, -1.5, 0);
      root.add(bodyMesh);
    }

    // Card captions
    for (let i = 0; i < cardCount; i++) {
      const captionGeo = ctx.fontAtlas.createTextGeometry(cardNames[i], {
        fontSize: 0.18,
        fontFamily: 'JetBrains Mono',
        fontWeight: 700,
        letterSpacing: 0.08,
        lineHeight: 1.4
      });
      if (captionGeo) {
        const captionMesh = new THREE.Mesh(
          captionGeo,
          new THREE.MeshStandardMaterial({ color: colors.paper })
        );
        captionMesh.position.y = -(cardHeight / 2 + 0.3);
        captionMesh.position.z = 0.001;
        cards[i].add(captionMesh);
      }
    }
  }

  // Update card visuals based on strip offset
  const updateCardVisuals = () => {
    cards.forEach((card) => {
      // Calculate world position relative to camera
      const worldX = card.userData.baseX - state.stripOffset;
      const distFromCenter = Math.abs(worldX);
      const isFocused = distFromCenter < cardPitch / 2;

      if (isFocused) {
        // Focused card: counter-rotate to face camera, scale 1.0, opacity 1.0
        card.rotation.y = -stripGroup.rotation.y;
        card.scale.set(1.0, 1.0, 1.0);
        card.userData.opacity = 1.0;
        card.userData.underline.visible = true;
      } else {
        // Non-focused: scale 0.92, opacity 1.0→0.55 by distance
        card.rotation.y = 0;
        card.scale.set(0.92, 0.92, 0.92);
        const maxDist = cardPitch * (cardCount / 2);
        card.userData.opacity = Math.max(0.55, 1.0 - (distFromCenter / maxDist) * 0.45);
        card.userData.underline.visible = false;
      }

      // Apply opacity to all meshes
      card.traverse((node) => {
        if (node.isMesh && node.material) {
          node.material.transparent = true;
          node.material.opacity = card.userData.opacity;
        }
      });
    });
  };

  // Snap to nearest card on scroll end
  const snapToNearest = () => {
    if (state.isSnapping) return;
    state.isSnapping = true;

    let nearestIdx = 0;
    let minDist = Infinity;

    cards.forEach((card, idx) => {
      const worldX = card.userData.baseX - state.stripOffset;
      const dist = Math.abs(worldX);
      if (dist < minDist) {
        minDist = dist;
        nearestIdx = idx;
      }
    });

    const targetOffset = (nearestIdx - Math.floor(cardCount / 2)) * cardPitch;

    if (state.snapTimeline) state.snapTimeline.kill();

    state.snapTimeline = gsap.to(state, {
      stripOffset: targetOffset,
      duration: 0.9,
      ease: 'cubic-bezier(0.165, 0.84, 0.44, 1)',
      overwrite: 'auto',
      onUpdate: updateCardVisuals,
      onComplete: () => {
        state.isSnapping = false;
        state.focusIndex = nearestIdx;
      }
    });
  };

  // Scroll event handler
  const handleScroll = (event) => {
    if (state.isSnapping) return;

    const delta = event.deltaY || 0;
    state.stripOffset += delta * 0.0005;

    updateCardVisuals();

    clearTimeout(state.scrollTimer);
    state.scrollTimer = setTimeout(snapToNearest, 200);
  };

  root.userData.handlers = {
    scroll: handleScroll
  };

  // Apply parallax-scroll cinematic primitive
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](stripGroup, { intensity: 0.5 });
  }

  // Initialize visuals
  updateCardVisuals();

  // Cleanup function
  root.userData.cleanup = () => {
    if (state.snapTimeline) state.snapTimeline.kill();
    clearTimeout(state.scrollTimer);

    root.traverse((node) => {
      if (node.isMesh) {
        if (node.geometry) node.geometry.dispose();
        if (node.material) {
          if (Array.isArray(node.material)) {
            node.material.forEach(mat => mat.dispose());
          } else {
            node.material.dispose();
          }
        }
      }
    });

    if (texture) texture.dispose();
  };

  return root;
}
